    "    t2 = TexCoord.xxxy + vec4( -dx, 0, dx,    -dy); //  A  B  C\n"
    "    t3 = TexCoord.xxxy + vec4( -dx, 0, dx,      0); //  D  E  F\n"
    "    t4 = TexCoord.xxxy + vec4( -dx, 0, dx,     dy); //  G  H  I\n"
    "    t5 = TexCoord.xxxy + vec4( -dx, 0, dx, 2.0*dy); // G5 H5 I5\n"
    "    t6 = TexCoord.xyyy + vec4(-2.0*dx,-dy, 0,  dy); // A0 D0 G0\n"
    "    t7 = TexCoord.xyyy + vec4( 2.0*dx,-dy, 0,  dy); // C4 F4 I4\n"
    "}\n"
    "\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define IN in\n"
    "#define tex2D texture\n"
    "out vec4 FragColor;\n"
    "#else\n"
    "#define IN varying\n"
    "#define FragColor gl_FragColor\n"
    "#define tex2D texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "#define PRECISION mediump\n"
    "#else\n"
    "#define PRECISION\n"
    "#endif\n"
    "\n"
    "uniform PRECISION int FrameDirection;\n"
    "uniform PRECISION int FrameCount;\n"
    "uniform PRECISION vec2 OutputSize;\n"
    "uniform PRECISION vec2 TextureSize;\n"
    "uniform PRECISION vec2 InputSize;\n"
    "uniform sampler2D decal;\n"
    "IN vec2 texCoord;\n"
    "IN vec4 t1;\n"
    "IN vec4 t2;\n"
    "IN vec4 t3;\n"
    "IN vec4 t4;\n"
    "IN vec4 t5;\n"
    "IN vec4 t6;\n"
    "IN vec4 t7;\n"
    "\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "uniform PRECISION float XBR_Y_WEIGHT;\n"
    "uniform PRECISION float XBR_EQ_THRESHOLD;\n"
    "uniform PRECISION float XBR_LV1_COEFFICIENT;\n"
    "uniform PRECISION float XBR_LV2_COEFFICIENT;\n"
    "uniform PRECISION float small_details;\n"
    "#else\n"
    "#define XBR_Y_WEIGHT 48.0\n"
    "#define XBR_EQ_THRESHOLD 15.0\n"
    "#define XBR_LV1_COEFFICIENT 0.5\n"
    "#define XBR_LV2_COEFFICIENT 2.0\n"
    "#define small_details 0.0\n"
    "#endif\n"
    "// END PARAMETERS //\n"
    "\n"
    "const float coef         = 2.0;\n"
    "const vec3 rgbw          = vec3(14.352, 28.176, 5.472);\n"
    "const vec4 eq_threshold  = vec4(15.0, 15.0, 15.0, 15.0);\n"
    "\n"
    "// Tone Rebellion remake: the three globals below are macros instead of\n"
    "// non-constant global initializers, which GLSL ES (WebGL 2) refuses.\n"
    "#define delta   vec4(1.0/XBR_SCALE, 1.0/XBR_SCALE, 1.0/XBR_SCALE, 1.0/XBR_SCALE)\n"
    "#define delta_l vec4(0.5/XBR_SCALE, 1.0/XBR_SCALE, 0.5/XBR_SCALE, 1.0/XBR_SCALE)\n"
    "#define delta_u (delta_l.yxwz)\n"
    "\n"
    "const  vec4 Ao = vec4( 1.0, -1.0, -1.0, 1.0 );\n"
    "const  vec4 Bo = vec4( 1.0,  1.0, -1.0,-1.0 );\n"
    "const  vec4 Co = vec4( 1.5,  0.5, -0.5, 0.5 );\n"
    "const  vec4 Ax = vec4( 1.0, -1.0, -1.0, 1.0 );\n"
    "const  vec4 Bx = vec4( 0.5,  2.0, -0.5,-2.0 );\n"
    "const  vec4 Cx = vec4( 1.0,  1.0, -0.5, 0.0 );\n"
    "const  vec4 Ay = vec4( 1.0, -1.0, -1.0, 1.0 );\n"
    "const  vec4 By = vec4( 2.0,  0.5, -2.0,-0.5 );\n"
    "const  vec4 Cy = vec4( 2.0,  0.0, -1.0, 0.5 );\n"
    "const  vec4 Ci = vec4(0.25, 0.25, 0.25, 0.25);\n"
    "\n"
    "const vec3 Y = vec3(0.2126, 0.7152, 0.0722);\n"
    "\n"
    "// Difference between vector components.\n"
    "vec4 df(vec4 A, vec4 B)\n"
    "{\n"
    "    return vec4(abs(A-B));\n"
    "}\n"
    "\n"
    "// Compare two vectors and return their components are different.\n"
    "vec4 diff(vec4 A, vec4 B)\n"
    "{\n"
    "    return vec4(notEqual(A, B));\n"
    "}\n"
    "\n"
    "// Determine if two vector components are equal based on a threshold.\n"
    "vec4 eq(vec4 A, vec4 B)\n"
    "{\n"
    "    return (step(df(A, B), vec4(XBR_EQ_THRESHOLD)));\n"
    "}\n"
    "\n"
    "// Determine if two vector components are NOT equal based on a threshold.\n"
    "vec4 neq(vec4 A, vec4 B)\n"
    "{\n"
    "    return (vec4(1.0, 1.0, 1.0, 1.0) - eq(A, B));\n"
    "}\n"
    "\n"
    "// Weighted distance.\n"
    "vec4 wd(vec4 a, vec4 b, vec4 c, vec4 d, vec4 e, vec4 f, vec4 g, vec4 h)\n"
    "{\n"
    "    return (df(a,b) + df(a,c) + df(d,e) + df(d,f) + 4.0*df(g,h));\n"
    "}\n"
    "\n"
    "vec4 weighted_distance(vec4 a, vec4 b, vec4 c, vec4 d, vec4 e, vec4 f, vec4 g, vec4 h, vec4 i, vec4 j, vec4 k, vec4 l)\n"
    "{\n"
    "	return (df(a,b) + df(a,c) + df(d,e) + df(d,f) + df(i,j) + df(k,l) + 2.0*df(g,h));\n"
    "}\n"
    "\n"
    "float c_df(vec3 c1, vec3 c2) \n"
    "{\n"
    "      vec3 df = abs(c1 - c2);\n"
    "      return df.r + df.g + df.b;\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    vec4 edri, edr, edr_l, edr_u, px; // px = pixel, edr = edge detection rule\n"
    "    vec4 irlv0, irlv1, irlv2l, irlv2u, block_3d;\n"
    "    vec4 fx, fx_l, fx_u; // inequations of straight lines.\n"
    "\n"
    "    vec2 fp  = fract(texCoord*TextureSize);\n"
    "\n"
    "    vec3 A1 = tex2D(decal, t1.xw ).xyz;\n"
    "    vec3 B1 = tex2D(decal, t1.yw ).xyz;\n"
    "    vec3 C1 = tex2D(decal, t1.zw ).xyz;\n"
    "    vec3 A  = tex2D(decal, t2.xw ).xyz;\n"
    "    vec3 B  = tex2D(decal, t2.yw ).xyz;\n"
    "    vec3 C  = tex2D(decal, t2.zw ).xyz;\n"
    "    vec3 D  = tex2D(decal, t3.xw ).xyz;\n"
    "    vec3 E  = tex2D(decal, t3.yw ).xyz;\n"
    "    vec3 F  = tex2D(decal, t3.zw ).xyz;\n"
    "    vec3 G  = tex2D(decal, t4.xw ).xyz;\n"
    "    vec3 H  = tex2D(decal, t4.yw ).xyz;\n"
    "    vec3 I  = tex2D(decal, t4.zw ).xyz;\n"
    "    vec3 G5 = tex2D(decal, t5.xw ).xyz;\n"
    "    vec3 H5 = tex2D(decal, t5.yw ).xyz;\n"
    "    vec3 I5 = tex2D(decal, t5.zw ).xyz;\n"
    "    vec3 A0 = tex2D(decal, t6.xy ).xyz;\n"
    "    vec3 D0 = tex2D(decal, t6.xz ).xyz;\n"
    "    vec3 G0 = tex2D(decal, t6.xw ).xyz;\n"
    "    vec3 C4 = tex2D(decal, t7.xy ).xyz;\n"
    "    vec3 F4 = tex2D(decal, t7.xz ).xyz;\n"
    "    vec3 I4 = tex2D(decal, t7.xw ).xyz;\n"
    "\n"
    "    vec4 b  = vec4(dot(B ,rgbw), dot(D ,rgbw), dot(H ,rgbw), dot(F ,rgbw));\n"
    "    vec4 c  = vec4(dot(C ,rgbw), dot(A ,rgbw), dot(G ,rgbw), dot(I ,rgbw));\n"
    "    vec4 d  = b.yzwx;\n"
    "    vec4 e  = vec4(dot(E,rgbw));\n"
    "    vec4 f  = b.wxyz;\n"
    "    vec4 g  = c.zwxy;\n"
    "    vec4 h  = b.zwxy;\n"
    "    vec4 i  = c.wxyz;\n"
    "    \n"
    "	vec4 i4, i5, h5, f4;\n"
    "	\n"
    "	float y_weight = XBR_Y_WEIGHT;\n"
    "	\n"
    "	if (small_details < 0.5)\n"
    "	{\n"
    "		i4 = vec4(dot(I4,rgbw), dot(C1,rgbw), dot(A0,rgbw), dot(G5,rgbw));\n"
    "		i5 = vec4(dot(I5,rgbw), dot(C4,rgbw), dot(A1,rgbw), dot(G0,rgbw));\n"
    "		h5 = vec4(dot(H5,rgbw), dot(F4,rgbw), dot(B1,rgbw), dot(D0,rgbw));\n"
    "	}\n"
    "	else\n"
    "	{\n"
    "		i4 = mul( mat4x3(I4, C1, A0, G5), y_weight * Y );\n"
    "		i5 = mul( mat4x3(I5, C4, A1, G0), y_weight * Y );\n"
    "		h5 = mul( mat4x3(H5, F4, B1, D0), y_weight * Y );\n"
    "	}\n"
    "    f4 = h5.yzwx;\n"
    "\n"
    "    // These inequations define the line below which interpolation occurs.\n"
    "    fx   = (Ao*fp.y+Bo*fp.x); \n"
    "    fx_l = (Ax*fp.y+Bx*fp.x);\n"
    "    fx_u = (Ay*fp.y+By*fp.x);\n"
    "\n"
    "    irlv1 = irlv0 = diff(e,f) * diff(e,h);\n"
    "\n"
    "#ifdef CORNER_B\n"
    "    irlv1      = (irlv0 * ( neq(f,b) * neq(h,d) + eq(e,i) * neq(f,i4) * neq(h,i5) + eq(e,g) + eq(e,c) ) );\n"
    "#endif\n"
    "#ifdef CORNER_D\n"
    "    vec4 c1 = i4.yzwx;\n"
    "    vec4 g0 = i5.wxyz;\n"
    "    irlv1     = (irlv0  *  ( neq(f,b) * neq(h,d) + eq(e,i) * neq(f,i4) * neq(h,i5) + eq(e,g) + eq(e,c) ) * (diff(f,f4) * diff(f,i) + diff(h,h5) * diff(h,i) + diff(h,g) + diff(f,c) + eq(b,c1) * eq(d,g0)));\n"
    "#endif\n"
    "#ifdef CORNER_C\n"
    "    irlv1     = (irlv0  * ( neq(f,b) * neq(f,c) + neq(h,d) * neq(h,g) + eq(e,i) * (neq(f,f4) * neq(f,i4) + neq(h,h5) * neq(h,i5)) + eq(e,g) + eq(e,c)) );\n"
    "#endif\n"
    "\n"
    "    irlv2l = diff(e,g) * diff(d,g);\n"
    "    irlv2u = diff(e,c) * diff(b,c);\n"
    "\n"
    "    vec4 fx45i = clamp((fx   + delta   -Co - Ci)/(2.0*delta  ), 0.0, 1.0);\n"
    "    vec4 fx45  = clamp((fx   + delta   -Co     )/(2.0*delta  ), 0.0, 1.0);\n"
    "    vec4 fx30  = clamp((fx_l + delta_l -Cx     )/(2.0*delta_l), 0.0, 1.0);\n"
    "    vec4 fx60  = clamp((fx_u + delta_u -Cy     )/(2.0*delta_u), 0.0, 1.0);\n"
    "\n"
    "    vec4 wd1, wd2;\n"
    "	if (small_details < 0.5)\n"
    "	{\n"
    "		wd1 = wd( e, c,  g, i, h5, f4, h, f);\n"
    "		wd2 = wd( h, d, i5, f, i4,  b, e, i);\n"
    "	}\n"
    "	else\n"
    "	{\n"
    "		wd1 = weighted_distance( e, c, g, i, f4, h5, h, f, b, d, i4, i5);\n"
    "		wd2 = weighted_distance( h, d, i5, f, b, i4, e, i, g, h5, c, f4);\n"
    "	}\n"
    "\n"
    "    edri  = step(wd1, wd2) * irlv0;\n"
    "    edr   = step(wd1 + vec4(0.1, 0.1, 0.1, 0.1), wd2) * step(vec4(0.5, 0.5, 0.5, 0.5), irlv1);\n"
    "    edr_l = step( lv2_cf*df(f,g), df(h,c) ) * irlv2l * edr;\n"
    "    edr_u = step( lv2_cf*df(h,c), df(f,g) ) * irlv2u * edr;\n"
    "\n"
    "    fx45  = edr   * fx45;\n"
    "    fx30  = edr_l * fx30;\n"
    "    fx60  = edr_u * fx60;\n"
    "    fx45i = edri  * fx45i;\n"
    "\n"
    "    px = step(df(e,f), df(e,h));\n"
    "\n"
    "#ifdef SMOOTH_TIPS\n"
    "    vec4 maximos = max(max(fx30, fx60), max(fx45, fx45i));\n"
    "#endif\n"
    "#ifndef SMOOTH_TIPS\n"
    "    vec4 maximos = max(max(fx30, fx60), fx45);\n"
    "#endif\n"
    "\n"
    "    vec3 res1 = E;\n"
    "    res1 = mix(res1, mix(H, F, px.x), maximos.x);\n"
    "    res1 = mix(res1, mix(B, D, px.z), maximos.z);\n"
    "    \n"
    "    vec3 res2 = E;\n"
    "    res2 = mix(res2, mix(F, B, px.y), maximos.y);\n"
    "    res2 = mix(res2, mix(D, H, px.w), maximos.w);\n"
    "    \n"
    "    vec3 res = mix(res1, res2, step(c_df(E, res1), c_df(E, res2)));\n"
    "\n"
    "    FragColor.xyz = res;\n"
    "}\n"
    "#endif\n"
    "\n";

/* shaders/libretro/hqx/shader-files/hqx-pass1.glsl */
static const char g_gl_shader_5[] =
    "/*\n"
    "* Copyright (C) 2003 Maxim Stepin ( maxst@hiend3d.com )\n"
    "*\n"
    "* Copyright (C) 2010 Cameron Zemek ( grom@zeminvaders.net )\n"
    "*\n"
    "* Copyright (C) 2014 Jules Blok ( jules@aerix.nl )\n"
    "*\n"
    "* This program is free software; you can redistribute it and/or\n"
    "* modify it under the terms of the GNU Lesser General Public\n"
    "* License as published by the Free Software Foundation; either\n"
    "* version 2.1 of the License, or (at your option) any later version.\n"
    "*\n"
    "* This program is distributed in the hope that it will be useful,\n"
    "* but WITHOUT ANY WARRANTY; without even the implied warranty of\n"
    "* MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the GNU\n"
    "* Lesser General Public License for more details.\n"
    "*\n"
    "* You should have received a copy of the GNU Lesser General Public\n"
    "* License along with this program; if not, write to the Free Software\n"
    "* Foundation, Inc., 59 Temple Place, Suite 330, Boston, MA 02111-1307 USA\n"
    "*/\n"
    "\n"
    "// Compatibility #ifdefs needed for parameters\n"
    "#ifdef GL_ES\n"
    "#define COMPAT_PRECISION mediump\n"
    "precision mediump float;\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "// Parameter lines go here:\n"
    "#pragma parameter trY \"Y Threshold\" 48.0 0.0 255.0 1.0\n"
    "#pragma parameter trU \"U Threshold\" 7.0 0.0 255.0 1.0\n"
    "#pragma parameter trV \"V Threshold\" 6.0 0.0 255.0 1.0\n"
    "#ifdef PARAMETER_UNIFORM\n"
    "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
    "uniform COMPAT_PRECISION float trY;\n"
    "uniform COMPAT_PRECISION float trU;\n"
    "uniform COMPAT_PRECISION float trV;\n"
    "#else\n"
    "#define trY 48.0\n"
    "#define trU 7.0\n"
    "#define trV 6.0\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "vec3 yuv_threshold = vec3(0.188235294, 0.02745098, 0.023529412);\n"
    "#else\n"
    "vec3 yuv_threshold = vec3(trY/255.0, trU/255.0, trV/255.0);\n"
    "#endif\n"
    "const mat3 yuv = mat3(0.299, -0.169, 0.5, 0.587, -0.331, -0.419, 0.114, 0.5, -0.081);\n"
    "const vec3 yuv_offset = vec3(0.0, 0.5, 0.5);\n"
    "\n"
    "bool diff(vec3 yuv1, vec3 yuv2) {\n"
    "	bvec3 res = greaterThan(abs((yuv1 + yuv_offset) - (yuv2 + yuv_offset)) , yuv_threshold);\n"
    "	return res.x || res.y || res.z;\n"
    "}\n"
    "\n"
    "#if defined(VERTEX)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING out\n"
    "#define COMPAT_ATTRIBUTE in\n"
    "#define COMPAT_TEXTURE texture\n"
    "#else\n"
    "#define COMPAT_VARYING varying \n"
    "#define COMPAT_ATTRIBUTE attribute \n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#define COMPAT_PRECISION mediump\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
    "COMPAT_ATTRIBUTE vec4 COLOR;\n"
    "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
    "COMPAT_VARYING vec4 COL0;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "COMPAT_VARYING vec4 t1;\n"
    "COMPAT_VARYING vec4 t2;\n"
    "COMPAT_VARYING vec4 t3;\n"
    "\n"
    "uniform mat4 MVPMatrix;\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "\n"
    "#define vTexCoord TEX0.xy\n"
    "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
    "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
    "\n"
    "void main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    COL0 = COLOR;\n"
    "    TEX0.xy = TexCoord.xy;\n"
    "	float	dx	=	SourceSize.z;\n"
    "	float	dy	=	SourceSize.w;\n"
    "	//   +----+----+----+\n"
    "	//   |    |    |    |\n"
    "	//   | w1 | w2 | w3 |\n"
    "	//   +----+----+----+\n"
    "	//   |    |    |    |\n"
    "	//   | w4 | w5 | w6 |\n"
    "	//   +----+----+----+\n"
    "	//   |    |    |    |\n"
    "	//   | w7 | w8 | w9 |\n"
    "	//   +----+----+----+\n"
    "	t1	=	vTexCoord.xxxy + vec4(-dx, 0, dx, -dy); //  w1 | w2 | w3;\n"
    "	t2	=	vTexCoord.xxxy + vec4(-dx, 0, dx,   0); //  w4 | w5 | w6;\n"
    "	t3	=	vTexCoord.xxxy + vec4(-dx, 0, dx,  dy); //  w7 | w8 | w9;\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "\n"
    "#if __VERSION__ >= 130\n"
    "#define COMPAT_VARYING in\n"
    "#define COMPAT_TEXTURE texture\n"
    "out vec4 FragColor;\n"
    "#else\n"
    "#define COMPAT_VARYING varying\n"
    "#define FragColor gl_FragColor\n"
    "#define COMPAT_TEXTURE texture2D\n"
    "#endif\n"
    "\n"
    "#ifdef GL_ES\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "#define COMPAT_PRECISION mediump\n"
    "#else\n"
    "#define COMPAT_PRECISION\n"
    "#endif\n"
    "\n"
    "uniform COMPAT_PRECISION int FrameDirection;\n"
    "uniform COMPAT_PRECISION int FrameCount;\n"
    "uniform COMPAT_PRECISION vec2 OutputSize;\n"
    "uniform COMPAT_PRECISION vec2 TextureSize;\n"
    "uniform COMPAT_PRECISION vec2 InputSize;\n"
    "uniform sampler2D Texture;\n"
    "COMPAT_VARYING vec4 TEX0;\n"
    "COMPAT_VARYING vec4 t1;\n"
    "COMPAT_VARYING vec4 t2;\n"
    "COMPAT_VARYING vec4 t3;\n"
    "\n"
    "// compatibility #defines\n"
    "#define Source Texture\n"
    "#define vTexCoord TEX0.xy\n"
    "\n"
    "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
    "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
    "\n"
    "void main()\n"
    "{\n"
    "	vec3	w1	=	yuv * COMPAT_TEXTURE(Source, t1.xw).rgb;\n"
    "	vec3	w2	=	yuv * COMPAT_TEXTURE(Source, t1.yw).rgb;\n"
    "	vec3	w3	=	yuv * COMPAT_TEXTURE(Source, t1.zw).rgb;\n"
    "\n"
    "	vec3	w4	=	yuv * COMPAT_TEXTURE(Source, t2.xw).rgb;\n"
    "	vec3	w5	=	yuv * COMPAT_TEXTURE(Source, t2.yw).rgb;\n"
    "	vec3	w6	=	yuv * COMPAT_TEXTURE(Source, t2.zw).rgb;\n"
    "\n"
    "	vec3	w7	=	yuv * COMPAT_TEXTURE(Source, t3.xw).rgb;\n"
    "	vec3	w8	=	yuv * COMPAT_TEXTURE(Source, t3.yw).rgb;\n"
    "	vec3	w9	=	yuv * COMPAT_TEXTURE(Source, t3.zw).rgb;\n"
    "\n"
    "	vec3	pattern_1	=	vec3(diff(w5, w1),	diff(w5, w2),	diff(w5, w3));\n"
    "	vec3	pattern_2	=	vec3(diff(w5, w4),	false,	diff(w5, w6));\n"
    "	vec3	pattern_3	=	vec3(diff(w5, w7),	diff(w5, w8),	diff(w5, w9));\n"
    "	vec4	cross		=	vec4(diff(w4, w2),	diff(w2, w6),	diff(w8, w4),	diff(w6, w8));\n"
    "	\n"
    "	vec2	index;\n"
    "	index.x	=	dot(pattern_1, vec3(1, 2, 4)) +\n"
    "				dot(pattern_2, vec3(8, 0, 16)) +\n"
    "				dot(pattern_3, vec3(32, 64, 128));\n"
    "	index.y	=	dot(cross, vec4(1, 2, 4, 8));\n"
    "	\n"
    "	FragColor	=	vec4(index / vec2(255.0, 15.0), 0.0, 1.0);\n"
    "} \n"
    "#endif\n"
    "\n";

